package store

import (
	"database/sql"
	"fmt"
	"strings"

	"shingo/protocol/migrate"
	"shingocore/store/schema"
)

// RetiredChain is the last version of the chain the baseline retires: a
// database born on the baseline records 1..RetiredChain, and the baseline is
// generated by booting RetiredChainRelease, the release that carries that
// whole chain (internal/schemadump.GenerateBaseline). Core starts on no
// database that lacks one of those versions; RetiredChainRelease is the
// release that applies them. The release tool reads RetiredChain as versions
// this file declares (shared/scripts/release MigrationVersions).
const (
	RetiredChain        = 184
	RetiredChainRelease = "v0.17.1"
)

// migrate brings the database to this build's schema, or refuses it.
//
//   - No schema_migrations and no table in schema public: a new database. It
//     is born on the baseline (store/schema/baseline.sql), applied as one
//     statement by applyBaseline: every table, index, constraint, comment and
//     seed row, and schema_migrations 1..RetiredChain.
//   - No schema_migrations, but tables: refused. That is a partial restore (a
//     dump restored without schema_migrations, or a hand-made schema), and
//     nothing can tell what shape it is.
//   - schema_migrations without some version of 1..RetiredChain: refused,
//     naming the versions and RetiredChainRelease, the release that applies
//     them. This build no longer carries the chain that did; a database below
//     v183 passes through that release first. Holes, not MAX(version): a
//     branch build that merged out of order can stand at a high version
//     without a lower one.
//
// A refusal writes nothing. Then the migrations above RetiredChain run through
// the shared runner, protocol/migrate, which carries the two correctness
// layers:
//
//  1. Transactional invariant: each migration's DDL/DML and its
//     schema_migrations row insert commit in the same transaction. Either both
//     land or neither does.
//  2. Self-heal on startup: for a migration with a non-nil verify, the
//     post-condition is checked before the schema_migrations gate is trusted.
//     A row that says "applied" without the state present is deleted and the
//     migration re-applied.
//
// migrationList's entries have verify taking schema.Querier; migrate.Querier
// has the identical method set, so the wrap below is a closure, not a
// rewrite. Baseline 0: Core's chain owns schema_migrations from v1, so the
// runner seeds nothing.
func (db *DB) migrate() error {
	fresh, err := checkRetiredChain(db.DB)
	if err != nil {
		return err
	}
	if fresh {
		if err := applyBaseline(db.DB, schema.Baseline); err != nil {
			return err
		}
	}
	ms := migrationList()
	wrapped := make([]migrate.Migration, 0, len(ms))
	for _, m := range ms {
		verify := m.verify
		wrapped = append(wrapped, migrate.Migration{
			Version: m.version,
			Name:    m.name,
			Fn:      m.fn,
			Verify: func(q migrate.Querier) bool {
				if verify == nil {
					return true
				}
				return verify(q)
			},
		})
	}
	return migrate.Run(db.DB, migrate.Postgres, 0, wrapped)
}

// checkRetiredChain reads the two facts migrate decides on and returns whether
// the database is new, or the refusal. It only reads.
func checkRetiredChain(q *sql.DB) (fresh bool, err error) {
	var hasMigrations bool
	var tables int
	if err := q.QueryRow(`SELECT to_regclass('public.schema_migrations') IS NOT NULL,
		(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
		  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p'))`).Scan(&hasMigrations, &tables); err != nil {
		return false, fmt.Errorf("read the schema's state: %w", err)
	}
	if !hasMigrations {
		if tables > 0 {
			return false, fmt.Errorf("Core tables present but no schema_migrations: restore the whole dump "+
				"(schema public holds %d tables and no schema_migrations; Core changed nothing)", tables)
		}
		return true, nil
	}
	rows, err := q.Query(`SELECT v FROM generate_series(1, $1::int) AS v
		WHERE NOT EXISTS (SELECT 1 FROM schema_migrations m WHERE m.version = v) ORDER BY v`, RetiredChain)
	if err != nil {
		return false, fmt.Errorf("read schema_migrations: %w", err)
	}
	defer rows.Close()
	var missing []int
	for rows.Next() {
		var v int
		if err := rows.Scan(&v); err != nil {
			return false, fmt.Errorf("read schema_migrations: %w", err)
		}
		missing = append(missing, v)
	}
	if err := rows.Err(); err != nil {
		return false, fmt.Errorf("read schema_migrations: %w", err)
	}
	if len(missing) > 0 {
		return false, fmt.Errorf("schema_migrations is missing %s of v1–v%d, which this build no longer carries: "+
			"start %s on this database first (it applies them), then this release; Core changed nothing",
			formatVersions(missing), RetiredChain, RetiredChainRelease)
	}
	return false, nil
}

// applyBaseline runs the baseline as ONE Exec. With no arguments pgx sends it
// on the simple query protocol (pgx v5 Conn.exec: "Always use simple protocol
// when there are no arguments"), and Postgres runs a multi-statement simple
// query as one implicit transaction: all of it commits or none of it does,
// never part. A failing statement anywhere in it leaves no table behind
// (TestBaseline_AFailureLateInItLeavesNoTable). A Core that dies part-way
// does NOT stop it: the whole text is already one message on the server, so
// the orphaned backend runs it to the end and commits it whole, and a boot
// while the orphan still holds its locks fails on lock_timeout (55P03) and
// the next restart boots the born database. Only the backend ending (it is
// terminated, or Postgres crashes) leaves nothing, and the next boot births
// the database again. Measured both ways in the clean-model round
// (build/proof-scale, proof 5.3). The baseline sets no session
// setting (the generator strips them), so the pool connection that ran it
// keeps Core's caps (TestBaseline_PoolKeepsCoresSessionCaps).
func applyBaseline(db *sql.DB, baseline string) error {
	if _, err := db.Exec(baseline); err != nil {
		return fmt.Errorf("apply the baseline to an empty database: %w", err)
	}
	return nil
}

// formatVersions writes ascending versions as ranges: v72, v179–v183.
func formatVersions(vs []int) string {
	var parts []string
	for i := 0; i < len(vs); {
		j := i
		for j+1 < len(vs) && vs[j+1] == vs[j]+1 {
			j++
		}
		if j == i {
			parts = append(parts, fmt.Sprintf("v%d", vs[i]))
		} else {
			parts = append(parts, fmt.Sprintf("v%d–v%d", vs[i], vs[j]))
		}
		i = j + 1
	}
	return strings.Join(parts, ", ")
}

// migration is one numbered, tracked schema change above RetiredChain.
//
// fn is the apply function: it runs inside a per-version transaction
// alongside the schema_migrations row insert (protocol/migrate's Run).
//
// verify is the post-condition check: given a Querier, true iff the schema
// state the migration is supposed to produce is present. It runs on startup
// BEFORE the schema_migrations gate: if a row says "applied" but verify
// returns false, the runner deletes the row and re-applies the migration. It
// catches a deploy that recorded the row without the DDL, and operator drift
// (a DROPped column, a restored backup behind schema_migrations). An absence
// is asserted with the absence helpers (schema.ColumnAbsent and its siblings),
// never a negated Exists (TestMigrationVerifyPredicatesAssertAbsenceWithTheAbsenceHelpers).
// nil means trust schema_migrations. verify must be cheap: it runs on every
// boot for every applied migration.
type migration struct {
	version int
	name    string
	fn      func(tx *sql.Tx) error
	verify  func(q schema.Querier) bool
}

// migrationList is every migration above RetiredChain, in version order
// (TestMigrationList_Shape). A new entry is a numbered migration; the baseline
// is regenerated after it (make schema-baseline), so a database born on the
// new baseline records it too.
func migrationList() []migration {
	return []migration{}
}

// latestMigrationVersion is the highest version this build records: the last
// entry of migrationList, or RetiredChain while the list is empty. Derived
// once at package init, before any goroutine that could race it exists.
var latestMigrationVersion = func() int {
	if ms := migrationList(); len(ms) > 0 {
		return max(RetiredChain, ms[len(ms)-1].version)
	}
	return RetiredChain
}()

// LatestMigrationVersion returns the highest schema migration version this
// build records. It is derived from the migration list and RetiredChain (not a
// hand-maintained constant), so it can never drift from them.
func LatestMigrationVersion() int { return latestMigrationVersion }
